import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached 128x128 PNG bytes of the prayer notification icon (ultra-lightweight ~20KB)
/// Pre-cached 128x128 PNG bytes of the prayer notification icon
Uint8List? _cachedIconBytes;

Uint8List get kPrayerNotificationLargeIconBytes {
  if (_cachedIconBytes != null) return _cachedIconBytes!;
  try {
    _cachedIconBytes = base64Decode(_rawIconBase64);
    return _cachedIconBytes!;
  } catch (e) {
    // Return empty Uint8List if base64 decoding encounters invalid padding or corruption
    return Uint8List(0);
  }
}

const String _rawIconBase64 =
  '';

